local variables = require "wa.variables"

local R = require "core.lib.rathena"
local TEMP_WRPC_TEXT = variables.character_temporary_table "wrpc_text"
local TEMP_WRPD_TEXT = variables.character_temporary_table "wrpd_text"
local TEMP_WRPP_TEXT = variables.character_temporary_table "wrpp_text"
local TEMP_VIEWPX = variables.character_temporary_table "viewpx"
local TEMP_VIEWPY = variables.character_temporary_table "viewpy"
local TEMP_WRPP = variables.character_temporary_table "wrpp"

return function(player, conversation, npc, ...)
  local map, warp_size, i = "", 0, 0
  local args = table.pack(...)
  R.adelete(TEMP_WRPC_TEXT, player, 0, R.asize(TEMP_WRPC_TEXT, player))
  R.adelete(TEMP_WRPD_TEXT, player, 0, R.asize(TEMP_WRPD_TEXT, player))
  R.adelete(TEMP_WRPP_TEXT, player, 0, R.asize(TEMP_WRPP_TEXT, player))
  R.adelete(TEMP_VIEWPX, player, 0, R.asize(TEMP_VIEWPX, player))
  R.adelete(TEMP_VIEWPY, player, 0, R.asize(TEMP_VIEWPY, player))
  map = npc.map
  if (map == "prontera") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Izlude", "Geffen", "Payon", "Morocc", "Orc Dungeon", "Alberta")
    R.asetarray(TEMP_WRPP, player, 0, 600, 1200, 1200, 1200, 1700, 1800)
    R.asetarray(TEMP_VIEWPX, player, 0, 151, 29, 282, 152)
    R.asetarray(TEMP_VIEWPY, player, 0, 29, 207, 200, 326)
  elseif (map == "alberta") then
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1800, 1800)
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Payon", "Morocc", "Prontera")
    R.asetarray(TEMP_VIEWPX, player, 0, 28, 113, 0, 0)
    R.asetarray(TEMP_VIEWPY, player, 0, 229, 60, 0, 0)
  elseif (map == "aldebaran") then
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200, 1800, 1700)
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Geffen", "Juno", "Izlude", "Mjolnir Dead Pit")
  elseif (map == "comodo") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Morocc", "Comodo Pharos Beacon", "Umbala")
    R.asetarray(TEMP_WRPP, player, 0, 1800, 1200, 1800)
  elseif (map == "cmd_fild07") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Comodo", "Morocc")
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200)
  elseif (map == "geffen") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Prontera", "Al De Baran", "Orc Dungeon", "Mjolnir Dead Pit")
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200, 1700, 1700)
    R.asetarray(TEMP_VIEWPX, player, 0, 120, 203)
    R.asetarray(TEMP_VIEWPY, player, 0, 62, 123)
  elseif (map == "izlude") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Geffen", "Payon", "Morocc", "Al De Baran")
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200, 1200, 1800)
  elseif (map == "morocc") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Prontera", "Payon", "Alberta", "Comodo", "Comodo Pharos Beacon")
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200, 1800, 1800, 1200)
    R.asetarray(TEMP_VIEWPX, player, 0, 156, 163, 28, 292)
    R.asetarray(TEMP_VIEWPY, player, 0, 97, 260, 167, 211)
  elseif (map == "umbala") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Comodo")
    R.asetarray(TEMP_WRPP, player, 0, 1800)
  elseif (map == "payon") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Prontera", "Alberta", "Morocc")
    R.asetarray(TEMP_WRPP, player, 0, 1200, 1200, 1200)
  elseif (map == "yuno") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Al De Baran")
    R.asetarray(TEMP_WRPP, player, 0, 1200)
    R.asetarray(TEMP_VIEWPX, player, 0, 328, 278, 153, 0)
    R.asetarray(TEMP_VIEWPY, player, 0, 108, 221, 187, 0)
  elseif (map == "job3_rune01") then
    R.asetarray(TEMP_WRPD_TEXT, player, 0, "Izlude", "Geffen", "Payon", "Morocc", "Alberta")
    R.asetarray(TEMP_WRPP, player, 0, 600, 1200, 1200, 1200, 1800)
  end
  warp_size = R.asize(TEMP_WRPD_TEXT, player)
